// Brute force: time O(n^2), space O(1)
class Solution {
public:
    vector<int> twoSum(vector<int>& nums, int target) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if ((long long)nums[i] + nums[j] == target) return {i, j};
            }
        }
        return {};
    }
};

// Brute force: time O(n + m), space O(n + m)
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        vector<int> a, b;
        for (ListNode* p = l1; p; p = p->next) a.push_back(p->val);
        for (ListNode* p = l2; p; p = p->next) b.push_back(p->val);
        size_t len = max(a.size(), b.size());
        vector<int> sum;
        int carry = 0;
        for (size_t i = 0; i < len; i++) {
            int t = carry;
            if (i < a.size()) t += a[i];
            if (i < b.size()) t += b[i];
            sum.push_back(t % 10);
            carry = t / 10;
        }
        if (carry) sum.push_back(carry);
        ListNode* head = new ListNode(sum[0]);
        ListNode* tail = head;
        for (size_t i = 1; i < sum.size(); i++) {
            tail->next = new ListNode(sum[i]);
            tail = tail->next;
        }
        return head;
    }
};

