// Brute force: time O(n^2), space O(n)
class Solution {
public:
    bool isValid(string s) {
        bool changed = true;
        while (changed) {
            changed = false;
            for (size_t i = 0; i + 1 < s.size(); i++) {
                if ((s[i] == '(' && s[i + 1] == ')') || (s[i] == '[' && s[i + 1] == ']') || (s[i] == '{' && s[i + 1] == '}')) {
                    s.erase(i, 2);
                    changed = true;
                    break;
                }
            }
        }
        return s.empty();
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int i = 0; i < n; i++) {
            long long sum = 0;
            for (int j = i; j < n; j++) {
                sum += nums[j];
                best = max(best, sum);
            }
        }
        return (int)best;
    }
};

