// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size(), best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                best = max(best, prices[j] - prices[i]);
            }
        }
