// Brute force: time O((R*C)^2), space O(R*C)
class Solution {
public:
    int numIslands(vector<vector<char>>& grid) {
        int rows = grid.size(), cols = rows ? grid[0].size() : 0;
        vector<vector<int>> label(rows, vector<int>(cols, 0));
        int next = 1;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (grid[r][c] == '1') label[r][c] = next++;
        int dy[4] = {1, -1, 0, 0}, dx[4] = {0, 0, 1, -1};
        bool changed = true;
        while (changed) {
            changed = false;
            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    if (!label[r][c]) continue;
                    for (int k = 0; k < 4; k++) {
                        int ny = r + dy[k], nx = c + dx[k];
                        if (ny >= 0 && ny < rows && nx >= 0 && nx < cols && label[ny][nx] && label[ny][nx] < label[r][c]) {
                            label[r][c] = label[ny][nx];
                            changed = true;
                        }
                    }
                }
            }
        }
        set<int> roots;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                if (label[r][c]) roots.insert(label[r][c]);
        return (int)roots.size();
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* reverseList(ListNode* head) {
        vector<int> vals;
        for (ListNode* p = head; p; p = p->next) vals.push_back(p->val);
        reverse(vals.begin(), vals.end());
        int i = 0;
        for (ListNode* p = head; p; p = p->next) p->val = vals[i++];
        return head;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    void moveZeroes(vector<int>& nums) {
        vector<int> tmp;
        for (int x : nums) if (x != 0) tmp.push_back(x);
        while (tmp.size() < nums.size()) tmp.push_back(0);
        nums = tmp;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    bool containsDuplicate(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (nums[i] == nums[j]) return true;
        return false;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int majorityElement(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int count = 0;
            for (int j = 0; j < n; j++) if (nums[j] == nums[i]) count++;
            if (count > n / 2) return nums[i];
        }
        return -1;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    bool isAnagram(string s, string t) {
        if (s.size() != t.size()) return false;
        for (char c : s) {
            size_t pos = t.find(c);
            if (pos == string::npos) return false;
            t.erase(pos, 1);
        }
        return t.empty();
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    int lengthOfLastWord(string s) {
        vector<string> words;
        string cur;
        for (char c : s) {
            if (c == ' ') {
                if (!cur.empty()) words.push_back(cur);
                cur.clear();
            } else cur.push_back(c);
        }
        if (!cur.empty()) words.push_back(cur);
        return words.empty() ? 0 : (int)words.back().size();
    }
};

// Brute force: time O(n*m), space O(m)
class Solution {
public:
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        vector<bool> used(nums2.size(), false);
        vector<int> out;
        for (int x : nums1) {
            for (size_t j = 0; j < nums2.size(); j++) {
                if (!used[j] && nums2[j] == x) {
                    used[j] = true;
                    out.push_back(x);
                    break;
                }
            }
        }
        sort(out.begin(), out.end());
        return out;
    }
};

// Brute force: time O(n^2), space O(1) extra
class Solution {
public:
    vector<int> productExceptSelf(vector<int>& nums) {
        int n = nums.size();
        vector<int> result(n, 1);
        for (int i = 0; i < n; i++) {
            long long p = 1;
            for (int j = 0; j < n; j++) if (j != i) p *= nums[j];
            result[i] = (int)p;
        }
        return result;
    }
};

// Brute force: time O(n^3), space O(n)
class Solution {
public:
    vector<vector<int>> merge(vector<vector<int>>& intervals) {
        vector<vector<int>> cur = intervals;
        bool changed = true;
        while (changed) {
            changed = false;
            for (size_t i = 0; i < cur.size() && !changed; i++) {
                for (size_t j = i + 1; j < cur.size(); j++) {
                    if (cur[i][0] <= cur[j][1] && cur[j][0] <= cur[i][1]) {
                        cur[i][0] = min(cur[i][0], cur[j][0]);
                        cur[i][1] = max(cur[i][1], cur[j][1]);
                        cur.erase(cur.begin() + j);
                        changed = true;
                        break;
                    }
                }
            }
        }
        sort(cur.begin(), cur.end());
        return cur;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int subarraySum(vector<int>& nums, int k) {
        int n = nums.size(), count = 0;
        for (int i = 0; i < n; i++) {
            long long sum = 0;
            for (int j = i; j < n; j++) {
                sum += nums[j];
                if (sum == k) count++;
            }
        }
        return count;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int hIndex(vector<int>& citations) {
        int n = citations.size();
        for (int h = n; h >= 1; h--) {
            int count = 0;
            for (int c : citations) if (c >= h) count++;
            if (count >= h) return h;
        }
        return 0;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        for (int candidate = 1;; candidate++) {
            bool found = false;
            for (int x : nums) {
                if (x == candidate) { found = true; break; }
            }
            if (!found) return candidate;
        }
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    bool isPalindrome(string s) {
        string clean;
        for (char c : s) if (isalnum((unsigned char)c)) clean.push_back(tolower((unsigned char)c));
        string rev(clean.rbegin(), clean.rend());
        return clean == rev;
    }
};

// Brute force: time O(n log n), space O(n) (collect the distinct values, write them back)
class Solution {
public:
    int removeDuplicates(vector<int>& nums) {
        set<int> distinct(nums.begin(), nums.end());
        int k = 0;
        for (int v : distinct) nums[k++] = v;
        return k;
    }
};

// Brute force: time O(n^3), space O(1)
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int n = s.size(), best = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                bool unique = true;
                for (int a = i; a <= j && unique; a++)
                    for (int b = a + 1; b <= j; b++)
                        if (s[a] == s[b]) { unique = false; break; }
                if (unique) best = max(best, j - i + 1);
            }
        }
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int minSubArrayLen(int target, vector<int>& nums) {
        int n = nums.size(), best = 0;
        for (int i = 0; i < n; i++) {
            long long sum = 0;
            for (int j = i; j < n; j++) {
                sum += nums[j];
                if (sum >= target) {
                    if (best == 0 || j - i + 1 < best) best = j - i + 1;
                    break;
                }
            }
        }
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int characterReplacement(string s, int k) {
        int n = s.size(), best = 0;
        for (int i = 0; i < n; i++) {
            int counts[26] = {0}, most = 0;
            for (int j = i; j < n; j++) {
                most = max(most, ++counts[s[j] - 'A']);
                if (j - i + 1 - most <= k) best = max(best, j - i + 1);
            }
        }
        return best;
    }
};

// Brute force: time O(m * n log n), space O(n)
class Solution {
public:
    bool checkInclusion(string s1, string s2) {
        int n = s1.size(), m = s2.size();
        sort(s1.begin(), s1.end());
        for (int i = 0; i + n <= m; i++) {
            string w = s2.substr(i, n);
            sort(w.begin(), w.end());
            if (w == s1) return true;
        }
        return false;
    }
};

// Brute force: time O(n^2), space O(1) extra
class Solution {
public:
    vector<int> dailyTemperatures(vector<int>& temperatures) {
        int n = temperatures.size();
        vector<int> answer(n, 0);
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (temperatures[j] > temperatures[i]) { answer[i] = j - i; break; }
            }
        }
        return answer;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int trap(vector<int>& height) {
        int n = height.size();
        long long water = 0;
        for (int i = 0; i < n; i++) {
            int leftMax = 0, rightMax = 0;
            for (int j = 0; j <= i; j++) leftMax = max(leftMax, height[j]);
            for (int j = i; j < n; j++) rightMax = max(rightMax, height[j]);
            water += min(leftMax, rightMax) - height[i];
        }
        return (int)water;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int largestRectangleArea(vector<int>& heights) {
        int n = heights.size();
        long long best = 0;
        for (int i = 0; i < n; i++) {
            int low = heights[i];
            for (int j = i; j < n; j++) {
                low = min(low, heights[j]);
                best = max(best, (long long)low * (j - i + 1));
            }
        }
        return (int)best;
    }
};

