// Brute force: time O(max(piles) * n), space O(1)
class Solution {
public:
    int minEatingSpeed(vector<int>& piles, int h) {
        int hi = *max_element(piles.begin(), piles.end());
        for (int k = 1; k < hi; k++) {
            long long hours = 0;
            for (int p : piles) hours += (p + k - 1) / k;
            if (hours <= h) return k;
        }
        return hi;
    }
};

// Brute force: time O(sum(weights) * n), space O(1)
class Solution {
public:
    int shipWithinDays(vector<int>& weights, int days) {
        long long start = *max_element(weights.begin(), weights.end()), total = 0;
        for (int w : weights) total += w;
        for (long long cap = start; cap < total; cap++) {
            long long load = 0;
            int need = 1;
            for (int w : weights) {
                if (load + w > cap) { need++; load = 0; }
                load += w;
            }
            if (need <= days) return (int)cap;
        }
        return (int)total;
    }
};

// Brute force: time O((n+m) log(n+m)), space O(n+m)
class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        vector<int> vals;
        for (ListNode* p = list1; p; p = p->next) vals.push_back(p->val);
        for (ListNode* p = list2; p; p = p->next) vals.push_back(p->val);
        sort(vals.begin(), vals.end());
        ListNode dummy(0);
        ListNode* tail = &dummy;
        for (int v : vals) {
            tail->next = new ListNode(v);
            tail = tail->next;
        }
        return dummy.next;
    }
};

// Brute force: time O(n), space O(1)
class Solution {
public:
    ListNode* middleNode(ListNode* head) {
        int n = 0;
        for (ListNode* p = head; p; p = p->next) n++;
        ListNode* p = head;
        for (int i = 0; i < n / 2; i++) p = p->next;
        return p;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    bool isPalindrome(ListNode* head) {
        vector<int> vals;
        for (ListNode* p = head; p; p = p->next) vals.push_back(p->val);
        vector<int> rev(vals.rbegin(), vals.rend());
        return vals == rev;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        for (ListNode* cur = head; cur; cur = cur->next) {
            ListNode* prev = cur;
            while (prev->next) {
                if (prev->next->val == cur->val) prev->next = prev->next->next;
                else prev = prev->next;
            }
        }
        return head;
    }
};

// Brute force: time O(n), space O(1)
class Solution {
public:
    ListNode* removeNthFromEnd(ListNode* head, int n) {
        int len = 0;
        for (ListNode* p = head; p; p = p->next) len++;
        int idx = len - n;
        if (idx == 0) return head->next;
        ListNode* p = head;
        for (int i = 0; i < idx - 1; i++) p = p->next;
        p->next = p->next->next;
        return head;
    }
};

// Brute force: time O(n), space O(1)
class Solution {
public:
    ListNode* swapPairs(ListNode* head) {
        for (ListNode* p = head; p && p->next; p = p->next->next)
            swap(p->val, p->next->val);
        return head;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* oddEvenList(ListNode* head) {
        vector<int> vals;
        for (ListNode* p = head; p; p = p->next) vals.push_back(p->val);
        vector<int> out;
        for (size_t i = 0; i < vals.size(); i += 2) out.push_back(vals[i]);
        for (size_t i = 1; i < vals.size(); i += 2) out.push_back(vals[i]);
        size_t k = 0;
        for (ListNode* p = head; p; p = p->next) p->val = out[k++];
        return head;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    ListNode* sortList(ListNode* head) {
        for (ListNode* i = head; i; i = i->next)
            for (ListNode* j = i->next; j; j = j->next)
                if (j->val < i->val) swap(i->val, j->val);
        return head;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    void reorderList(ListNode* head) {
        vector<ListNode*> nodes;
        for (ListNode* p = head; p; p = p->next) nodes.push_back(p);
        int lo = 0, hi = (int)nodes.size() - 1;
        vector<ListNode*> order;
        while (lo <= hi) {
            order.push_back(nodes[lo++]);
            if (lo <= hi) order.push_back(nodes[hi--]);
        }
        for (size_t i = 0; i + 1 < order.size(); i++) order[i]->next = order[i + 1];
        if (!order.empty()) order.back()->next = nullptr;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        vector<int> vals;
        for (ListNode* p = head; p; p = p->next) vals.push_back(p->val);
        for (size_t i = 0; i + k <= vals.size(); i += k)
            reverse(vals.begin() + i, vals.begin() + i + k);
        size_t idx = 0;
        for (ListNode* p = head; p; p = p->next) p->val = vals[idx++];
        return head;
    }
};

// Brute force: time O(n), space O(n)
TreeNode* buildMirrorCopy(TreeNode* node) {
    if (!node) return nullptr;
    TreeNode* c = new TreeNode(node->val);
    c->left = buildMirrorCopy(node->right);
    c->right = buildMirrorCopy(node->left);
    return c;
}

bool sameShapeAndVals(TreeNode* a, TreeNode* b) {
    if (!a && !b) return true;
    if (!a || !b) return false;
    return a->val == b->val && sameShapeAndVals(a->left, b->left) && sameShapeAndVals(a->right, b->right);
}

class Solution {
public:
    bool isSymmetric(TreeNode* root) {
        TreeNode* mirrored = buildMirrorCopy(root);
        return sameShapeAndVals(root, mirrored);
    }
};

// Brute force: time O(n^2), space O(h)
int heightOf(TreeNode* node) {
    if (!node) return 0;
    return 1 + max(heightOf(node->left), heightOf(node->right));
}

class Solution {
public:
    int diameterOfBinaryTree(TreeNode* root) {
        if (!root) return 0;
        int through = heightOf(root->left) + heightOf(root->right);
        return max(through, max(diameterOfBinaryTree(root->left), diameterOfBinaryTree(root->right)));
    }
};

// Brute force: time O(n), space O(h) recursion
void inorderRec(TreeNode* node, vector<int>& out) {
    if (!node) return;
    inorderRec(node->left, out);
    out.push_back(node->val);
    inorderRec(node->right, out);
}

class Solution {
public:
    vector<int> inorderTraversal(TreeNode* root) {
        vector<int> out;
        inorderRec(root, out);
        return out;
    }
};

// Brute force: time O(n), space O(n)
void collectPathSums(TreeNode* node, int sum, vector<int>& sums) {
    if (!node) return;
    sum += node->val;
    if (!node->left && !node->right) sums.push_back(sum);
    collectPathSums(node->left, sum, sums);
    collectPathSums(node->right, sum, sums);
}

class Solution {
public:
    bool hasPathSum(TreeNode* root, int targetSum) {
        vector<int> sums;
        collectPathSums(root, 0, sums);
        for (int s : sums) if (s == targetSum) return true;
        return false;
    }
};

// Brute force: time O(n^2), space O(h)
int depthOf(TreeNode* node) {
    if (!node) return 0;
    return 1 + max(depthOf(node->left), depthOf(node->right));
}

class Solution {
public:
    bool isBalanced(TreeNode* root) {
        if (!root) return true;
        if (abs(depthOf(root->left) - depthOf(root->right)) > 1) return false;
        return isBalanced(root->left) && isBalanced(root->right);
    }
};

// Brute force: time O(n * h), space O(h)
void rightmostAtDepth(TreeNode* node, int depth, int target, TreeNode*& found) {
    if (!node) return;
    if (depth == target) { found = node; return; }
    rightmostAtDepth(node->left, depth + 1, target, found);
    rightmostAtDepth(node->right, depth + 1, target, found);
}

class Solution {
public:
    vector<int> rightSideView(TreeNode* root) {
        vector<int> out;
        for (int d = 0;; d++) {
            TreeNode* found = nullptr;
            rightmostAtDepth(root, 0, d, found);
            if (!found) break;
            out.push_back(found->val);
        }
        return out;
    }
};

// Brute force: time O(n^2), space O(h)
bool allLess(TreeNode* node, long long v) {
    if (!node) return true;
    return node->val < v && allLess(node->left, v) && allLess(node->right, v);
}

bool allGreater(TreeNode* node, long long v) {
    if (!node) return true;
    return node->val > v && allGreater(node->left, v) && allGreater(node->right, v);
}

class Solution {
public:
    bool isValidBST(TreeNode* root) {
        if (!root) return true;
        if (!allLess(root->left, root->val) || !allGreater(root->right, root->val)) return false;
        return isValidBST(root->left) && isValidBST(root->right);
    }
};

// Brute force: time O(n log n), space O(n)
void collectVals(TreeNode* node, vector<int>& vals) {
    if (!node) return;
    vals.push_back(node->val);
    collectVals(node->left, vals);
    collectVals(node->right, vals);
}

class Solution {
public:
    int kthSmallest(TreeNode* root, int k) {
        vector<int> vals;
        collectVals(root, vals);
        sort(vals.begin(), vals.end());
        return vals[k - 1];
    }
};

// Brute force: time O(n * h), space O(h)
int countGoodRec(TreeNode* node, vector<int>& path) {
    if (!node) return 0;
    path.push_back(node->val);
    bool good = true;
    for (int v : path) if (v > node->val) good = false;
    int total = good ? 1 : 0;
    total += countGoodRec(node->left, path) + countGoodRec(node->right, path);
    path.pop_back();
    return total;
}

class Solution {
public:
    int goodNodes(TreeNode* root) {
        vector<int> path;
        return countGoodRec(root, path);
    }
};

// Brute force: time O(n), space O(n) (root-to-node paths, then the last shared node)
class Solution {
    bool path(TreeNode* r, TreeNode* target, vector<TreeNode*>& out) {
        if (!r) return false;
        out.push_back(r);
        if (r == target) return true;
        if (path(r->left, target, out) || path(r->right, target, out)) return true;
        out.pop_back();
        return false;
    }

public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        vector<TreeNode*> a, b;
        path(root, p, a);
        path(root, q, b);
        TreeNode* last = nullptr;
        for (size_t i = 0; i < a.size() && i < b.size() && a[i] == b[i]; i++) last = a[i];
        return last;
    }
};

// Brute force: time O(n), space O(n) (root-to-node paths, then the last shared node)
class Solution {
    bool path(TreeNode* r, TreeNode* target, vector<TreeNode*>& out) {
        if (!r) return false;
        out.push_back(r);
        if (r == target) return true;
        if (path(r->left, target, out) || path(r->right, target, out)) return true;
        out.pop_back();
        return false;
    }

public:
    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {
        vector<TreeNode*> a, b;
        path(root, p, a);
        path(root, q, b);
        TreeNode* last = nullptr;
        for (size_t i = 0; i < a.size() && i < b.size() && a[i] == b[i]; i++) last = a[i];
        return last;
    }
};

// Brute force: time O(n^2), space O(h)
long long downPath(TreeNode* node) {
    if (!node) return 0;
    return node->val + max(0LL, max(downPath(node->left), downPath(node->right)));
}

long long bestThrough(TreeNode* node) {
    if (!node) return LLONG_MIN;
    long long through = node->val + max(0LL, downPath(node->left)) + max(0LL, downPath(node->right));
    return max(through, max(bestThrough(node->left), bestThrough(node->right)));
}

class Solution {
public:
    int maxPathSum(TreeNode* root) {
        return (int)bestThrough(root);
    }
};

// Brute force: time O(n^2 log n), space O(1)
class Solution {
public:
    int lastStoneWeight(vector<int>& stones) {
        vector<int> s = stones;
        while (s.size() > 1) {
            sort(s.begin(), s.end());
            int a = s.back(); s.pop_back();
            int b = s.back(); s.pop_back();
            if (a != b) s.push_back(a - b);
        }
        return s.empty() ? 0 : s[0];
    }
};

// Brute force: time O(n log n), space O(1)
class Solution {
public:
    int findKthLargest(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end(), greater<int>());
        return nums[k - 1];
    }
};

// Brute force: time O(n^2 + n*k), space O(n)
class Solution {
public:
    vector<int> topKFrequent(vector<int>& nums, int k) {
        vector<int> distinct, cnt;
        for (int x : nums) {
            bool seen = false;
            for (int d : distinct) if (d == x) seen = true;
            if (!seen) distinct.push_back(x);
        }
        for (int d : distinct) {
            int c = 0;
            for (int x : nums) if (x == d) c++;
            cnt.push_back(c);
        }
        vector<int> out;
        vector<bool> used(distinct.size(), false);
        for (int round = 0; round < k; round++) {
            int best = -1;
            for (size_t i = 0; i < distinct.size(); i++) {
                if (used[i]) continue;
                if (best < 0 || cnt[i] > cnt[best] || (cnt[i] == cnt[best] && distinct[i] < distinct[best])) best = i;
            }
            used[best] = true;
            out.push_back(distinct[best]);
        }
        return out;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int minMeetingRooms(vector<vector<int>>& intervals) {
        int best = 0;
        for (auto& a : intervals) {
            int t = a[0], c = 0;
            for (auto& b : intervals) if (b[0] <= t && t < b[1]) c++;
            best = max(best, c);
        }
        return best;
    }
};

// Brute force: time O(n*k), space O(1)
class Solution {
public:
    vector<int> maxSlidingWindow(vector<int>& nums, int k) {
        vector<int> out;
        for (int i = 0; i + k <= (int)nums.size(); i++) {
            int m = nums[i];
            for (int j = i; j < i + k; j++) m = max(m, nums[j]);
            out.push_back(m);
        }
        return out;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int rob(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        vector<int> best(n, 0);
        for (int i = 0; i < n; i++) {
            int prev = 0;
            for (int j = 0; j + 2 <= i; j++) prev = max(prev, best[j]);
            best[i] = nums[i] + prev;
            ans = max(ans, best[i]);
        }
        return ans;
    }
};

// Brute force: time O(n^2), space O(n)
int robLine(const vector<int>& a, int lo, int hi) {
    int n = hi - lo, ans = 0;
    vector<int> best(n, 0);
    for (int i = 0; i < n; i++) {
        int prev = 0;
        for (int j = 0; j + 2 <= i; j++) prev = max(prev, best[j]);
        best[i] = a[lo + i] + prev;
        ans = max(ans, best[i]);
    }
    return ans;
}

class Solution {
public:
    int rob(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return nums[0];
        return max(robLine(nums, 0, n - 1), robLine(nums, 1, n));
    }
};

// Brute force: time O(2^(m+n)), space O(m+n)
int countPaths(int r, int c) {
    if (r == 1 || c == 1) return 1;
    return countPaths(r - 1, c) + countPaths(r, c - 1);
}

class Solution {
public:
    int uniquePaths(int m, int n) {
        return countPaths(m, n);
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int lengthOfLIS(vector<int>& nums) {
        int n = nums.size(), ans = 0;
        vector<int> len(n, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++)
                if (nums[j] < nums[i]) len[i] = max(len[i], len[j] + 1);
            ans = max(ans, len[i]);
        }
        return ans;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    bool canJump(vector<int>& nums) {
        int n = nums.size();
        vector<bool> ok(n, false);
        ok[0] = true;
        for (int i = 1; i < n; i++)
            for (int j = 0; j < i; j++)
                if (ok[j] && j + nums[j] >= i) { ok[i] = true; break; }
        return ok[n - 1];
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int jump(vector<int>& nums) {
        int n = nums.size();
        const int INF = 1e9;
        vector<int> best(n, INF);
        best[0] = 0;
        for (int i = 1; i < n; i++)
            for (int j = 0; j < i; j++)
                if (best[j] < INF && j + nums[j] >= i) best[i] = min(best[i], best[j] + 1);
        return best[n - 1];
    }
};

// Brute force: time O(2^n), space O(n)
int decodeFrom(const string& s, size_t i) {
    if (i == s.size()) return 1;
    if (s[i] == '0') return 0;
    int total = decodeFrom(s, i + 1);
    if (i + 1 < s.size()) {
        int two = (s[i] - '0') * 10 + (s[i + 1] - '0');
        if (two <= 26) total += decodeFrom(s, i + 2);
    }
    return total;
}

class Solution {
public:
    int numDecodings(string s) {
        return decodeFrom(s, 0);
    }
};

// Brute force: time O(n log n), space O(1) extra
class Solution {
public:
    vector<int> countBits(int n) {
        vector<int> out;
        for (int i = 0; i <= n; i++) {
            int c = 0;
            for (int x = i; x > 0; x >>= 1) c += x & 1;
            out.push_back(c);
        }
        return out;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxProduct(vector<int>& nums) {
        long long best = nums[0];
        for (size_t i = 0; i < nums.size(); i++) {
            long long prod = 1;
            for (size_t j = i; j < nums.size(); j++) {
                prod *= nums[j];
                best = max(best, prod);
            }
        }
        return (int)best;
    }
};

// Brute force: time O(n^3), space O(1) (test every substring)
class Solution {
public:
    string longestPalindrome(string s) {
        int n = s.size(), best = 0, from = 0;
        for (int i = 0; i < n; i++)
            for (int j = i; j < n; j++) {
                bool pal = true;
                for (int a = i, b = j; a < b; a++, b--) if (s[a] != s[b]) { pal = false; break; }
                if (pal && j - i + 1 > best) { best = j - i + 1; from = i; }
            }
        return s.substr(from, best);
    }
};

// Brute force: time O(rows * cols * min(rows, cols)^3), space O(1)
class Solution {
public:
    int maximalSquare(vector<vector<char>>& matrix) {
        int rows = matrix.size(), cols = matrix[0].size(), best = 0;
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                for (int side = 1; r + side <= rows && c + side <= cols; side++) {
                    bool ok = true;
                    for (int i = r; i < r + side && ok; i++)
                        for (int j = c; j < c + side; j++)
                            if (matrix[i][j] != '1') { ok = false; break; }
                    if (!ok) break;
                    best = max(best, side);
                }
        return best * best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int longestValidParentheses(string s) {
        int n = s.size(), best = 0;
        for (int i = 0; i < n; i++) {
            int balance = 0;
            for (int j = i; j < n; j++) {
                balance += s[j] == '(' ? 1 : -1;
                if (balance < 0) break;
                if (balance == 0) best = max(best, j - i + 1);
            }
        }
        return best;
    }
};

// Brute force: time O(2^n), space O(n)
class Solution {
public:
    int countSubsets(vector<int>& nums, int target) {
        return go(nums, 0, target);
    }

private:
    int go(vector<int>& nums, int i, int remaining) {
        if (i == (int)nums.size()) return remaining == 0 ? 1 : 0;
        int total = go(nums, i + 1, remaining);
        if (nums[i] <= remaining) total += go(nums, i + 1, remaining - nums[i]);
        return total;
    }
};

// Brute force: time O(n * 2^n), space O(n)
class Solution {
public:
    int partition(string s) {
        return go(s, 0);
    }

private:
    bool isPal(const string& s, int lo, int hi) {
        while (lo < hi) {
            if (s[lo] != s[hi]) return false;
            lo++;
            hi--;
        }
        return true;
    }

    int go(const string& s, int start) {
        if (start == (int)s.size()) return 1;
        int total = 0;
        for (int end = start; end < (int)s.size(); end++)
            if (isPal(s, start, end)) total += go(s, end + 1);
        return total;
    }
};

// Brute force: time O(S * n) where S is the total sum, space O(1)
class Solution {
public:
    int splitArray(vector<int>& nums, int k) {
        int limit = *max_element(nums.begin(), nums.end());
        while (true) {
            int parts = 1, run = 0;
            for (int x : nums) {
                if (run + x > limit) { parts++; run = x; }
                else run += x;
            }
            if (parts <= k) return limit;
            limit++;
        }
    }
};

// Brute force: time O(n!), space O(n)
class Solution {
public:
    int totalNQueens(int n) {
        vector<int> col(n, -1);
        return place(col, 0, n);
    }

private:
    int place(vector<int>& col, int row, int n) {
        if (row == n) return 1;
        int total = 0;
        for (int c = 0; c < n; c++) {
            bool ok = true;
            for (int r = 0; r < row; r++)
                if (col[r] == c || abs(col[r] - c) == row - r) { ok = false; break; }
            if (!ok) continue;
            col[row] = c;
            total += place(col, row + 1, n);
        }
        return total;
    }
};

// Brute force: time O(n * E), space O(n)
class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
        vector<bool> reached(n, false);
        reached[source] = true;
        bool changed = true;
        while (changed) {
            changed = false;
            for (auto& e : edges) {
                if (reached[e[0]] && !reached[e[1]]) { reached[e[1]] = true; changed = true; }
                if (reached[e[1]] && !reached[e[0]]) { reached[e[0]] = true; changed = true; }
            }
        }
        return reached[destination];
    }
};

// Brute force: time O(n * E), space O(n)
class Solution {
public:
    bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
        vector<bool> done(numCourses, false);
        int taken = 0;
        bool progress = true;
        while (progress) {
            progress = false;
            for (int course = 0; course < numCourses; course++) {
                if (done[course]) continue;
                bool ready = true;
                for (auto& p : prerequisites)
                    if (p[0] == course && !done[p[1]]) { ready = false; break; }
                if (ready) { done[course] = true; taken++; progress = true; }
            }
        }
        return taken == numCourses;
    }
};

// Brute force: time O(n * E), space O(n)
class Solution {
public:
    int countComponents(int n, vector<vector<int>>& edges) {
        vector<int> label(n);
        for (int i = 0; i < n; i++) label[i] = i;
        bool changed = true;
        while (changed) {
            changed = false;
            for (auto& e : edges) {
                int low = min(label[e[0]], label[e[1]]);
                if (label[e[0]] != low) { label[e[0]] = low; changed = true; }
                if (label[e[1]] != low) { label[e[1]] = low; changed = true; }
            }
        }
        int count = 0;
        for (int i = 0; i < n; i++) if (label[i] == i) count++;
        return count;
    }
};

// Brute force: time O(n * m + n log n), space O(m)
class Solution {
public:
    int findContentChildren(vector<int>& g, vector<int>& s) {
        vector<int> greed = g;
        sort(greed.begin(), greed.end());
        vector<bool> used(s.size(), false);
        int content = 0;
        for (int need : greed) {
            int pick = -1;
            for (int j = 0; j < (int)s.size(); j++)
                if (!used[j] && s[j] >= need && (pick == -1 || s[j] < s[pick])) pick = j;
            if (pick == -1) break;
            used[pick] = true;
            content++;
        }
        return content;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxArea(vector<int>& height) {
        int n = height.size(), best = 0;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                best = max(best, (j - i) * min(height[i], height[j]));
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int canCompleteCircuit(vector<int>& gas, vector<int>& cost) {
        int n = gas.size();
        for (int start = 0; start < n; start++) {
            int tank = 0;
            bool ok = true;
            for (int step = 0; step < n; step++) {
                int i = (start + step) % n;
                tank += gas[i] - cost[i];
                if (tank < 0) { ok = false; break; }
            }
            if (ok) return start;
        }
        return -1;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        vector<int> best(n + 1, 0);
        for (int i = 1; i <= n; i++) {
            best[i] = best[i - 1];
            for (int j = 0; j < i; j++)
                best[i] = max(best[i], best[j] + prices[i - 1] - prices[j]);
        }
        return best[n];
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    vector<int> partitionLabels(string s) {
        vector<int> sizes;
        int n = s.size(), start = 0;
        while (start < n) {
            int end = start, i = start;
            while (i <= end) {
                for (int j = n - 1; j > end; j--)
                    if (s[j] == s[i]) { end = j; break; }
                i++;
            }
            sizes.push_back(end - start + 1);
            start = end + 1;
        }
        return sizes;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int candy(vector<int>& ratings) {
        int n = ratings.size();
        vector<int> give(n, 1);
        bool changed = true;
        while (changed) {
            changed = false;
            for (int i = 0; i < n; i++) {
                if (i > 0 && ratings[i] > ratings[i - 1] && give[i] <= give[i - 1]) {
                    give[i] = give[i - 1] + 1;
                    changed = true;
                }
                if (i + 1 < n && ratings[i] > ratings[i + 1] && give[i] <= give[i + 1]) {
                    give[i] = give[i + 1] + 1;
                    changed = true;
                }
            }
        }
        int total = 0;
        for (int x : give) total += x;
        return total;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int eraseOverlapIntervals(vector<vector<int>>& intervals) {
        vector<vector<int>> a = intervals;
        sort(a.begin(), a.end());
        int n = a.size(), keep = 0;
        vector<int> chain(n, 1);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < i; j++)
                if (a[j][1] <= a[i][0]) chain[i] = max(chain[i], chain[j] + 1);
            keep = max(keep, chain[i]);
        }
        return n - keep;
    }
};

// Brute force: time O(n log n), space O(n)
class Solution {
public:
    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {
        vector<vector<int>> all = intervals;
        all.push_back(newInterval);
        sort(all.begin(), all.end());
        vector<vector<int>> result;
        for (auto& iv : all) {
            if (!result.empty() && result.back()[1] >= iv[0]) result.back()[1] = max(result.back()[1], iv[1]);
            else result.push_back(iv);
        }
        return result;
    }
};

// Brute force: time O(n^3), space O(1)
class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        int best = 0;
        for (int x : nums) {
            int length = 1;
            while (find(nums.begin(), nums.end(), x + length) != nums.end()) length++;
            best = max(best, length);
        }
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        for (size_t i = 0; i < nums.size(); i++) {
            int count = 0;
            for (size_t j = 0; j < nums.size(); j++)
                if (nums[j] == nums[i]) count++;
            if (count == 1) return nums[i];
        }
        return 0;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int missingNumber(vector<int>& nums) {
        int n = nums.size();
        for (int v = 0; v <= n; v++)
            if (find(nums.begin(), nums.end(), v) == nums.end()) return v;
        return -1;
    }
};

// Brute force: time O(32), space O(1)
class Solution {
