// Brute force: time O(steps^2), space O(steps)
class Solution {
public:
    bool isHappy(int n) {
        vector<long long> seen;
        long long x = n;
        while (x != 1) {
            if (find(seen.begin(), seen.end(), x) != seen.end()) return false;
            seen.push_back(x);
            long long total = 0;
            while (x > 0) {
                total += (x % 10) * (x % 10);
                x /= 10;
            }
            x = total;
        }
        return true;
    }
};

// Brute force: time O(n), space O(1)
class Solution {
public:
    int romanToInt(string s) {
        vector<pair<string, int>> table = {
            {"M", 1000}, {"CM", 900}, {"D", 500}, {"CD", 400}, {"C", 100}, {"XC", 90},
            {"L", 50}, {"XL", 40}, {"X", 10}, {"IX", 9}, {"V", 5}, {"IV", 4}, {"I", 1}};
        int total = 0;
        size_t pos = 0;
        while (pos < s.size()) {
            for (auto& entry : table) {
                if (s.compare(pos, entry.first.size(), entry.first) == 0) {
                    total += entry.second;
                    pos += entry.first.size();
                    break;
                }
            }
        }
        return total;
    }
};

// Brute force: time O(n * sqrt(n)), space O(1)
class Solution {
public:
    int countPrimes(int n) {
        int count = 0;
        for (int i = 2; i < n; i++) {
            bool prime = true;
            for (int d = 2; d < i; d++)
                if (i % d == 0) { prime = false; break; }
            if (prime) count++;
        }
        return count;
    }
};

// Brute force: time O(exp), space O(1)
class Solution {
public:
    int powMod(int base, int exp, int mod) {
        unsigned long long m = mod, b = base % m, result = 1 % m;
        for (int i = 0; i < exp; i++) result = result * b % m;
        return (int)result;
    }
};

// Brute force: time O(log x), space O(log x)
class Solution {
public:
    int reverse(int x) {
        long long value = x;
        bool negative = value < 0;
        if (negative) value = -value;
        string digits = to_string(value);
        std::reverse(digits.begin(), digits.end());
        long long result = stoll(digits);
        if (negative) result = -result;
        if (result < INT_MIN || result > INT_MAX) return 0;
        return (int)result;
    }
};

// Brute force: time O(n log n), space O(n)
class Solution {
public:
    vector<int> sortedSquares(vector<int>& nums) {
