// Brute force: time O(n^2), space O(1) extra
class Solution {
public:
    vector<int> findDisappearedNumbers(vector<int>& nums) {
        int n = nums.size();
        vector<int> res;
        for (int v = 1; v <= n; v++) {
            bool found = false;
            for (int x : nums) {
                if (x == v) { found = true; break; }
            }
            if (!found) res.push_back(v);
        }
        return res;
    }
};

// Brute force: time O(n^2), space O(n^2)
class Solution {
public:
    vector<vector<int>> generate(int numRows) {
        vector<vector<int>> res;
        for (int i = 0; i < numRows; i++) {
            vector<int> row;
            long long c = 1;
            for (int j = 0; j <= i; j++) {
                row.push_back((int)c);  // C(i, j) from the binomial formula
                c = c * (i - j) / (j + 1);
            }
            res.push_back(row);
        }
        return res;
    }
};

// Brute force: time O(n*k), space O(1)
class Solution {
public:
    void rotate(vector<int>& nums, int k) {
        int n = nums.size();
        if (n == 0) return;
        k %= n;
        for (int step = 0; step < k; step++) {
            int last = nums[n - 1];
            for (int i = n - 1; i > 0; i--) nums[i] = nums[i - 1];
            nums[0] = last;
        }
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    void sortColors(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++)
            for (int j = 0; j + 1 < n - i; j++)
                if (nums[j] > nums[j + 1]) swap(nums[j], nums[j + 1]);
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    void nextPermutation(vector<int>& nums) {
        int n = nums.size();
        // try each position from the right: is there a bigger value after it?
        for (int i = n - 2; i >= 0; i--) {
            int best = -1;
            for (int j = i + 1; j < n; j++) {
                if (nums[j] > nums[i] && (best == -1 || nums[j] < nums[best])) best = j;
            }
            if (best != -1) {
                swap(nums[i], nums[best]);
                sort(nums.begin() + i + 1, nums.end());
                return;
            }
        }
        sort(nums.begin(), nums.end());
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int findDuplicate(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if (nums[i] == nums[j]) return nums[i];
        return -1;
    }
};

// Brute force: time O(m*n), space O(m*n)
class Solution {
public:
    vector<int> spiralOrder(vector<vector<int>>& matrix) {
        vector<int> res;
        if (matrix.empty()) return res;
        int m = matrix.size(), n = matrix[0].size();
        vector<vector<bool>> seen(m, vector<bool>(n, false));
        int dr[4] = {0, 1, 0, -1}, dc[4] = {1, 0, -1, 0};
        int r = 0, c = 0, d = 0;
        for (int k = 0; k < m * n; k++) {
            res.push_back(matrix[r][c]);
            seen[r][c] = true;
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= m || nc < 0 || nc >= n || seen[nr][nc]) {
                d = (d + 1) % 4;
                nr = r + dr[d];
                nc = c + dc[d];
            }
            r = nr;
            c = nc;
        }
        return res;
    }
};

// Brute force: time O(n^2), space O(n^2)
class Solution {
public:
    void rotate(vector<vector<int>>& matrix) {
        int n = matrix.size();
        vector<vector<int>> copy = matrix;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) matrix[j][n - 1 - i] = copy[i][j];
    }
};

// Brute force: time O(m*n*(m+n)), space O(m*n)
class Solution {
public:
    void setZeroes(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        vector<vector<int>> orig = matrix;
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (orig[i][j] == 0) {
                    for (int k = 0; k < n; k++) matrix[i][k] = 0;
                    for (int k = 0; k < m; k++) matrix[k][j] = 0;
                }
            }
        }
    }
};

// Brute force: time O(n^3), space O(1)
class Solution {
public:
    int threeSumClosest(vector<int>& nums, int target) {
        int n = nums.size();
        long long best = (long long)nums[0] + nums[1] + nums[2];
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++) {
                    long long s = (long long)nums[i] + nums[j] + nums[k];
                    if (llabs(s - target) < llabs(best - target)) best = s;
                }
        return (int)best;
    }
};

