// Brute force: time O(n), space O(n) (recursive evaluation from the end)
class Solution {
    long long eval(vector<string>& t, int& i) {
        string tok = t[i--];
        if (tok == "+" || tok == "-" || tok == "*" || tok == "/") {
            long long b = eval(t, i);
            long long a = eval(t, i);
            if (tok == "+") return a + b;
            if (tok == "-") return a - b;
            if (tok == "*") return a * b;
            return a / b;
        }
        return stoll(tok);
    }

public:
    int evalRPN(vector<string>& tokens) {
        int i = (int)tokens.size() - 1;
        return (int)eval(tokens, i);
    }
};

// Brute force: time O(n^2), space O(1) extra
class Solution {
public:
    vector<int> nextGreaterElements(vector<int>& nums) {
        int n = nums.size();
        vector<int> res(n, -1);
        for (int i = 0; i < n; i++) {
            for (int k = 1; k < n; k++) {
                int v = nums[(i + k) % n];
                if (v > nums[i]) { res[i] = v; break; }
            }
        }
        return res;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int carFleet(int target, vector<int>& position, vector<int>& speed) {
        int n = position.size();
        int fleets = 0;
        for (int i = 0; i < n; i++) {
            long long di = target - position[i], si = speed[i];
            bool blocked = false;
            // car i joins a fleet if some car ahead takes at least as long to arrive
            for (int j = 0; j < n && !blocked; j++) {
                if (position[j] > position[i]) {
                    long long dj = target - position[j], sj = speed[j];
                    if (dj * si >= di * sj) blocked = true;
                }
            }
            if (!blocked) fleets++;
        }
        return fleets;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int sumSubarrayMins(vector<int>& arr) {
        const long long MOD = 1000000007LL;
        int n = arr.size();
        long long total = 0;
        for (int i = 0; i < n; i++) {
            int mn = arr[i];
            for (int j = i; j < n; j++) {
                mn = min(mn, arr[j]);
                total = (total + mn) % MOD;
            }
        }
        return (int)total;
    }
};

// Brute force: time O(2^n), space O(n)
class Solution {
    bool go(const string& s, int start, unordered_set<string>& dict) {
        if (start == (int)s.size()) return true;
        for (int end = start + 1; end <= (int)s.size(); end++)
            if (dict.count(s.substr(start, end - start)) && go(s, end, dict)) return true;
        return false;
    }

public:
    bool wordBreak(string s, vector<string>& wordDict) {
        unordered_set<string> dict(wordDict.begin(), wordDict.end());
        return go(s, 0, dict);
    }
};

// Brute force: time O(n^3), space O(1)
class Solution {
public:
    int countSubstrings(string s) {
        int n = s.size(), count = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i; j < n; j++) {
                bool pal = true;
                for (int l = i, r = j; l < r; l++, r--) {
                    if (s[l] != s[r]) { pal = false; break; }
                }
                if (pal) count++;
            }
        }
        return count;
    }
};

// Brute force: time O(2^n), space O(n)
class Solution {
public:
    int findTargetSumWays(vector<int>& nums, int target) {
        return go(nums, 0, target);
    }
private:
    int go(const vector<int>& nums, int i, int remaining) {
        if (i == (int)nums.size()) return remaining == 0 ? 1 : 0;
        return go(nums, i + 1, remaining - nums[i]) + go(nums, i + 1, remaining + nums[i]);
    }
};

// Brute force: time O(n log n + d^2) for d distinct values, space O(d)
class Solution {
public:
    int deleteAndEarn(vector<int>& nums) {
        map<int, int> cnt;
        for (int x : nums) cnt[x]++;
        vector<pair<int, int>> v(cnt.begin(), cnt.end());
        int d = v.size();
        vector<int> best(d, 0);  // best total when v[i] is the largest value taken
        int ans = 0;
        for (int i = 0; i < d; i++) {
            int prev = 0;
            for (int j = 0; j < i; j++)
                if (v[j].first <= v[i].first - 2) prev = max(prev, best[j]);
            best[i] = prev + v[i].first * v[i].second;
            ans = max(ans, best[i]);
        }
        return ans;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        vector<int> f(n + 3, 0);  // f[i]: best profit using days i..n-1 when free to buy on day i
        for (int i = n - 1; i >= 0; i--) {
            f[i] = f[i + 1];  // skip day i
            for (int j = i + 1; j < n; j++)  // buy on i, sell on j, rest on j+1
                f[i] = max(f[i], prices[j] - prices[i] + f[j + 2]);
        }
        return f[0];
    }
};

// Brute force: time O(2^m) over the length of s, space O(m)
class Solution {
public:
    int numDistinct(string s, string t) {
        return go(s, t, 0, 0);
    }
private:
    int go(const string& s, const string& t, int i, int j) {
        if (j == (int)t.size()) return 1;
        if (i == (int)s.size()) return 0;
        int ways = go(s, t, i + 1, j);  // skip s[i]
        if (s[i] == t[j]) ways += go(s, t, i + 1, j + 1);  // use s[i]
        return ways;
    }
};

// Brute force: time O(2^(m+n)), space O(m+n)
class Solution {
public:
    bool isMatch(string s, string p) {
        return go(s, p, 0, 0);
    }
private:
    bool go(const string& s, const string& p, int i, int j) {
        if (j == (int)p.size()) return i == (int)s.size();
        bool first = i < (int)s.size() && (p[j] == '.' || p[j] == s[i]);
        if (j + 1 < (int)p.size() && p[j + 1] == '*')
            return go(s, p, i, j + 2) || (first && go(s, p, i + 1, j));
        return first && go(s, p, i + 1, j + 1);
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int n = prices.size();
        int best = 0;
        // try every split point; best single trade on each side
        for (int k = 0; k <= n; k++) {
            int left = 0, mn = INT_MAX;
            for (int i = 0; i < k; i++) {
                mn = min(mn, prices[i]);
                left = max(left, prices[i] - mn);
            }
            int right = 0;
            mn = INT_MAX;
            for (int i = k; i < n; i++) {
                mn = min(mn, prices[i]);
                right = max(right, prices[i] - mn);
            }
            best = max(best, left + right);
        }
        return best;
    }
};

// Brute force: time O(n*E), space O(n)
class Solution {
public:
    int networkDelayTime(vector<vector<int>>& times, int n, int k) {
        const int INF = INT_MAX;
        vector<int> dist(n + 1, INF);
        dist[k] = 0;
        // Bellman-Ford: relax every edge up to n-1 times
        for (int round = 0; round < n - 1; round++) {
            bool changed = false;
            for (auto& e : times) {
                if (dist[e[0]] != INF && dist[e[0]] + e[2] < dist[e[1]]) {
                    dist[e[1]] = dist[e[0]] + e[2];
                    changed = true;
                }
            }
            if (!changed) break;
        }
        int best = 0;
        for (int i = 1; i <= n; i++) best = max(best, dist[i]);
        return best == INF ? -1 : best;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int findCircleNum(vector<vector<int>>& isConnected) {
        int n = isConnected.size();
        vector<bool> seen(n, false);
        int count = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            count++;
            dfs(isConnected, seen, i);
        }
        return count;
    }
private:
    void dfs(vector<vector<int>>& g, vector<bool>& seen, int u) {
        seen[u] = true;
        for (int v = 0; v < (int)g.size(); v++)
            if (g[u][v] == 1 && !seen[v]) dfs(g, seen, v);
    }
};

// Brute force: time O(E^2), space O(E)
class Solution {
public:
    vector<int> findRedundantConnection(vector<vector<int>>& edges) {
        int m = edges.size();
        // from the last edge backwards: removing it must leave the graph connected
        for (int skip = m - 1; skip >= 0; skip--) {
            vector<vector<int>> adj(m + 1);
            for (int i = 0; i < m; i++) {
                if (i == skip) continue;
                adj[edges[i][0]].push_back(edges[i][1]);
                adj[edges[i][1]].push_back(edges[i][0]);
            }
            vector<bool> seen(m + 1, false);
            vector<int> stack = {1};
            seen[1] = true;
            int reached = 1;
            while (!stack.empty()) {
                int u = stack.back();
                stack.pop_back();
                for (int v : adj[u]) {
                    if (!seen[v]) { seen[v] = true; reached++; stack.push_back(v); }
                }
            }
            if (reached == m) return edges[skip];
        }
        return {};
    }
};

// Brute force: time O(n^2 log n + n^3) worst case, space O(n^2)
class Solution {
public:
    int minCostConnectPoints(vector<vector<int>>& points) {
        int n = points.size();
        vector<array<int, 3>> edges;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                edges.push_back({abs(points[i][0] - points[j][0]) + abs(points[i][1] - points[j][1]), i, j});
        sort(edges.begin(), edges.end());
        // Kruskal with component labels, relabelling a whole component on merge
        vector<int> comp(n);
        for (int i = 0; i < n; i++) comp[i] = i;
        long long total = 0;
        int used = 0;
        for (auto& e : edges) {
            int a = comp[e[1]], b = comp[e[2]];
            if (a == b) continue;
            total += e[0];
            for (int i = 0; i < n; i++) if (comp[i] == b) comp[i] = a;
            if (++used == n - 1) break;
        }
        return (int)total;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int findMinArrowShots(vector<vector<int>>& points) {
        vector<vector<int>> left = points;
        int arrows = 0;
        while (!left.empty()) {
            // smallest right end among the remaining balloons; shoot there
            long long x = LLONG_MAX;
            for (auto& p : left) x = min(x, (long long)p[1]);
            vector<vector<int>> next;
            for (auto& p : left)
                if (!(p[0] <= x && x <= p[1])) next.push_back(p);
            left = next;
            arrows++;
        }
        return arrows;
    }
};

// Brute force: time O(T * 26) for T time units, space O(1) (simulate every unit of time)
class Solution {
public:
    int leastInterval(vector<char>& tasks, int n) {
        vector<int> left(26, 0), ready(26, 0);
        for (char c : tasks) left[c - 'A']++;
        int remaining = tasks.size(), time = 0;
        while (remaining > 0) {
            int pick = -1;
            for (int c = 0; c < 26; c++)
                if (left[c] > 0 && ready[c] <= time && (pick == -1 || left[c] > left[pick])) pick = c;
            if (pick != -1) {
                left[pick]--;
                remaining--;
                ready[pick] = time + n + 1;
            }
            time++;
        }
        return time;
    }
};

