// Brute force: time O(n log n), space O(n)
class Solution {
public:
    int nthUglyNumber(int n) {
        set<long long> pool;
        pool.insert(1);
        long long cur = 1;
        for (int i = 0; i < n; i++) {
            cur = *pool.begin();
            pool.erase(pool.begin());
            pool.insert(cur * 2);
            pool.insert(cur * 3);
            pool.insert(cur * 5);
        }
        return (int)cur;
    }
};

// Brute force: time O(n*h), space O(h)
class Solution {
public:
    vector<vector<int>> levelOrder(TreeNode* root) {
        vector<vector<int>> res;
        int h = height(root);
        for (int d = 0; d < h; d++) {
            vector<int> level;
            collect(root, d, level);  // rescan the whole tree for each depth
            res.push_back(level);
        }
        return res;
    }
private:
    int height(TreeNode* node) {
        if (!node) return 0;
        return 1 + max(height(node->left), height(node->right));
    }
    void collect(TreeNode* node, int depth, vector<int>& out) {
        if (!node) return;
        if (depth == 0) { out.push_back(node->val); return; }
        collect(node->left, depth - 1, out);
        collect(node->right, depth - 1, out);
    }
};

// Brute force: time O(n), space O(h)
void leafDepths(TreeNode *node, int d, int &best) {
    if (!node) return;
    if (!node->left && !node->right) best = min(best, d);
    leafDepths(node->left, d + 1, best);
    leafDepths(node->right, d + 1, best);
}

class Solution {
public:
    int minDepth(TreeNode* root) {
        if (!root) return 0;
        int best = INT_MAX;
        leafDepths(root, 1, best);
        return best;
    }
};

// Brute force: time O(n * h), space O(n * h)
void collect(TreeNode *node, string path, vector<string> &paths) {
    if (!node) return;
    path += to_string(node->val);
    if (!node->left && !node->right) { paths.push_back(path); return; }
    collect(node->left, path, paths);
    collect(node->right, path, paths);
}

class Solution {
public:
    int sumNumbers(TreeNode* root) {
        vector<string> paths;
        collect(root, "", paths);
        long long total = 0;
        for (auto &p : paths) total += stoll(p);
        return (int)total;
    }
};

// Brute force: time O(2^n) worst case, space O(h)
class Solution {
public:
    int rob(TreeNode* root) {
        if (!root) return 0;
        // option 1: rob this node, so skip both children and recurse on grandchildren
        int take = root->val;
        if (root->left) take += rob(root->left->left) + rob(root->left->right);
        if (root->right) take += rob(root->right->left) + rob(root->right->right);
        // option 2: skip this node
        int skip = rob(root->left) + rob(root->right);
        return max(take, skip);
    }
};

// Brute force: time O(n^2), space O(h)
int countFrom(TreeNode *node, long long remaining) {
    if (!node) return 0;
    int res = (node->val == remaining) ? 1 : 0;
    res += countFrom(node->left, remaining - node->val);
    res += countFrom(node->right, remaining - node->val);
    return res;
}

class Solution {
public:
    int pathSum(TreeNode* root, int targetSum) {
        if (!root) return 0;
        return countFrom(root, targetSum) + pathSum(root->left, targetSum) + pathSum(root->right, targetSum);
    }
};

// Brute force: time O(n^2), space O(n)
TreeNode *build(const vector<int> &pre, int &pos, const vector<int> &in, int lo, int hi) {
    if (lo > hi) return nullptr;
    TreeNode *node = new TreeNode(pre[pos++]);
    int mid = lo;
    while (in[mid] != node->val) mid++; // linear search for the root in inorder
    node->left = build(pre, pos, in, lo, mid - 1);
    node->right = build(pre, pos, in, mid + 1, hi);
    return node;
}

class Solution {
public:
    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
        int pos = 0;
        return build(preorder, pos, inorder, 0, (int)inorder.size() - 1);
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* removeElements(ListNode* head, int val) {
        vector<int> keep;
        for (ListNode *p = head; p; p = p->next)
            if (p->val != val) keep.push_back(p->val);
        ListNode dummy(0);
        ListNode *tail = &dummy;
        for (int x : keep) {
            tail->next = new ListNode(x);
            tail = tail->next;
        }
        return dummy.next;
    }
};

// Brute force: time O(n * k), space O(1)
class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        if (!head || !head->next) return head;
        int n = 0;
        for (ListNode *p = head; p; p = p->next) n++;
        k %= n;
        for (int i = 0; i < k; i++) {
            // move the last node to the front
            ListNode *prev = head;
            while (prev->next->next) prev = prev->next;
            ListNode *last = prev->next;
            prev->next = nullptr;
            last->next = head;
            head = last;
        }
        return head;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* partition(ListNode* head, int x) {
        vector<int> vals;
        for (ListNode *p = head; p; p = p->next)
            if (p->val < x) vals.push_back(p->val);
        for (ListNode *p = head; p; p = p->next)
            if (p->val >= x) vals.push_back(p->val);
        ListNode dummy(0);
        ListNode *tail = &dummy;
        for (int v : vals) {
            tail->next = new ListNode(v);
            tail = tail->next;
        }
        return dummy.next;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    ListNode* deleteDuplicates(ListNode* head) {
        vector<int> vals;
        for (ListNode *p = head; p; p = p->next) vals.push_back(p->val);
        ListNode dummy(0);
        ListNode *tail = &dummy;
        for (int v : vals) {
            int cnt = 0;
            for (int w : vals) if (w == v) cnt++; // rescan the whole list for every value
            if (cnt == 1) {
                tail->next = new ListNode(v);
                tail = tail->next;
            }
        }
        return dummy.next;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        vector<int> vals;
        for (ListNode *p = head; p; p = p->next) vals.push_back(p->val);
        reverse(vals.begin() + (left - 1), vals.begin() + right);
        ListNode dummy(0);
        ListNode *tail = &dummy;
        for (int v : vals) {
            tail->next = new ListNode(v);
            tail = tail->next;
        }
        return dummy.next;
    }
};

// Brute force: time O(n), space O(n)
class Solution {
public:
    int pairSum(ListNode* head) {
        vector<int> vals;
        for (ListNode *p = head; p; p = p->next) vals.push_back(p->val);
        int n = vals.size(), best = 0;
        for (int i = 0; i < n / 2; i++) best = max(best, vals[i] + vals[n - 1 - i]);
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int singleNumber(vector<int>& nums) {
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            int cnt = 0;
            for (int j = 0; j < n; j++) if (nums[j] == nums[i]) cnt++;
            if (cnt == 1) return nums[i];
        }
        return 0;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int integerBreak(int n) {
        vector<int> best(n + 1, 0);
        for (int i = 2; i <= n; i++) {
            for (int j = 1; j < i; j++) {
                // first piece j; the rest is either kept whole or broken further
                int rest = max(i - j, best[i - j]);
                best[i] = max(best[i], j * rest);
            }
        }
        return best[n];
    }
};

// Brute force: time O(amount^(number of coins)) worst case, space O(amount)
int ways(const vector<int> &coins, int idx, int amount) {
    if (amount == 0) return 1;
    if (idx == (int)coins.size()) return 0;
    int res = 0;
    for (int used = 0; used * coins[idx] <= amount; used++)
        res += ways(coins, idx + 1, amount - used * coins[idx]);
    return res;
}

class Solution {
public:
    int change(int amount, vector<int>& coins) {
        return ways(coins, 0, amount);
    }
};

// Brute force: time O(2^(m+n)), space O(m+n)
bool go(const string &a, const string &b, const string &c, int i, int j) {
    if (i == (int)a.size() && j == (int)b.size()) return true;
    int k = i + j;
    if (i < (int)a.size() && a[i] == c[k] && go(a, b, c, i + 1, j)) return true;
    if (j < (int)b.size() && b[j] == c[k] && go(a, b, c, i, j + 1)) return true;
    return false;
}

class Solution {
public:
    bool isInterleave(string s1, string s2, string s3) {
        if (s1.size() + s2.size() != s3.size()) return false;
        return go(s1, s2, s3, 0, 0);
    }
};

// Brute force: time O(2^(n+m)) worst case, space O(n+m)
bool match(const string &s, const string &p, int i, int j) {
    if (j == (int)p.size()) return i == (int)s.size();
    if (p[j] == '*') {
        // '*' matches empty, or swallows one more character
        if (match(s, p, i, j + 1)) return true;
        return i < (int)s.size() && match(s, p, i + 1, j);
    }
    if (i == (int)s.size()) return false;
    if (p[j] == '?' || p[j] == s[i]) return match(s, p, i + 1, j + 1);
    return false;
}

class Solution {
public:
    bool isMatch(string s, string p) {
        return match(s, p, 0, 0);
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int lengthOfLongestSubstringKDistinct(string s, int k) {
        int n = s.size(), best = 0;
        for (int i = 0; i < n; i++) {
            bool seen[256] = {};
            int distinct = 0;
            for (int j = i; j < n; j++) {
                unsigned char c = s[j];
                if (!seen[c]) { seen[c] = true; distinct++; }
                if (distinct > k) break;
                best = max(best, j - i + 1);
            }
        }
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int findMaxLength(vector<int>& nums) {
        int n = nums.size(), best = 0;
        for (int i = 0; i < n; i++) {
            int zeros = 0, ones = 0;
            for (int j = i; j < n; j++) {
                if (nums[j] == 0) zeros++; else ones++;
                if (zeros == ones) best = max(best, j - i + 1);
            }
        }
        return best;
    }
};

// Brute force: time O(9^3 * 9), space O(1) (compare every pair of cells)
class Solution {
public:
    bool isValidSudoku(vector<vector<char>>& board) {
        for (int a = 0; a < 81; a++)
            for (int b = a + 1; b < 81; b++) {
                int r1 = a / 9, c1 = a % 9, r2 = b / 9, c2 = b % 9;
                if (board[r1][c1] == '.' || board[r1][c1] != board[r2][c2]) continue;
                if (r1 == r2 || c1 == c2 || (r1 / 3 == r2 / 3 && c1 / 3 == c2 / 3)) return false;
            }
        return true;
    }
};

// Brute force: time O((m*n)^2), space O(m*n) (flood every region and test it for a border cell)
class Solution {
public:
    void solve(vector<vector<char>>& board) {
        int m = board.size(), n = m ? board[0].size() : 0;
        vector<vector<int>> seen(m, vector<int>(n, 0));
        int dr[4] = {1, -1, 0, 0}, dc[4] = {0, 0, 1, -1};
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++) {
                if (board[i][j] != 'O' || seen[i][j]) continue;
                vector<pair<int, int>> cells = {{i, j}};
                seen[i][j] = 1;
                bool border = false;
                for (size_t k = 0; k < cells.size(); k++) {
                    auto [r, c] = cells[k];
                    if (r == 0 || c == 0 || r == m - 1 || c == n - 1) border = true;
                    for (int d = 0; d < 4; d++) {
                        int a = r + dr[d], b = c + dc[d];
                        if (a >= 0 && b >= 0 && a < m && b < n && board[a][b] == 'O' && !seen[a][b]) {
                            seen[a][b] = 1;
                            cells.push_back({a, b});
                        }
                    }
                }
                if (!border) for (auto [r, c] : cells) board[r][c] = 'X';
            }
    }
};

// Brute force: time O((m*n)^2), space O(m*n)
class Solution {
public:
    vector<vector<int>> updateMatrix(vector<vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        vector<vector<int>> dist(m, vector<int>(n, INT_MAX));
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                for (int a = 0; a < m; a++)
                    for (int b = 0; b < n; b++)
                        if (mat[a][b] == 0) dist[i][j] = min(dist[i][j], abs(i - a) + abs(j - b));
        return dist;
    }
};

// Brute force: time O(E^(k+1)), space O(k)
void explore(int node, int dst, int edgesLeft, long long cost, const vector<vector<int>> &flights, long long &best) {
    if (cost >= best) return;
    if (node == dst) { best = cost; return; }
    if (edgesLeft == 0) return;
    for (auto &f : flights)
        if (f[0] == node) explore(f[1], dst, edgesLeft - 1, cost + f[2], flights, best);
}

class Solution {
public:
    int findCheapestPrice(int n, vector<vector<int>>& flights, int src, int dst, int k) {
        long long best = LLONG_MAX;
        explore(src, dst, k + 1, 0, flights, best);
        return best == LLONG_MAX ? -1 : (int)best;
    }
};

// Brute force: time O(maxEffort * m * n), space O(m*n)
class Solution {
public:
    int minimumEffortPath(vector<vector<int>>& heights) {
        int m = heights.size(), n = heights[0].size();
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        // try each effort limit in turn; the first one that lets us reach the end is the answer
        for (int limit = 0;; limit++) {
            vector<vector<char>> seen(m, vector<char>(n, 0));
            vector<pair<int, int>> st = {{0, 0}};
            seen[0][0] = 1;
            while (!st.empty()) {
                auto [i, j] = st.back();
                st.pop_back();
                if (i == m - 1 && j == n - 1) return limit;
                for (int d = 0; d < 4; d++) {
                    int a = i + dx[d], b = j + dy[d];
                    if (a < 0 || a >= m || b < 0 || b >= n || seen[a][b]) continue;
                    if (abs(heights[a][b] - heights[i][j]) > limit) continue;
                    seen[a][b] = 1;
                    st.push_back({a, b});
                }
            }
        }
    }
};

// Brute force: time O(maxTime * n^2), space O(n^2)
class Solution {
public:
    int swimInWater(vector<vector<int>>& grid) {
        int n = grid.size();
        int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
        // try each water level t; the first one where a path exists is the answer
        for (int t = max(grid[0][0], grid[n - 1][n - 1]);; t++) {
            vector<vector<char>> seen(n, vector<char>(n, 0));
            vector<pair<int, int>> st = {{0, 0}};
            seen[0][0] = 1;
            while (!st.empty()) {
                auto [i, j] = st.back();
                st.pop_back();
                if (i == n - 1 && j == n - 1) return t;
                for (int d = 0; d < 4; d++) {
                    int a = i + dx[d], b = j + dy[d];
                    if (a >= 0 && a < n && b >= 0 && b < n && !seen[a][b] && grid[a][b] <= t) {
                        seen[a][b] = 1;
                        st.push_back({a, b});
                    }
                }
            }
        }
    }
};

// Brute force: time O((m*n)^3), space O(1)
class Solution {
public:
    int maximalRectangle(vector<vector<int>>& matrix) {
        int m = matrix.size();
        if (m == 0) return 0;
        int n = matrix[0].size(), best = 0;
        for (int r1 = 0; r1 < m; r1++)
            for (int c1 = 0; c1 < n; c1++)
                for (int r2 = r1; r2 < m; r2++)
                    for (int c2 = c1; c2 < n; c2++) {
                        int area = (r2 - r1 + 1) * (c2 - c1 + 1);
                        if (area <= best) continue;
                        bool all = true;
                        for (int i = r1; i <= r2 && all; i++)
                            for (int j = c1; j <= c2; j++)
                                if (matrix[i][j] != 1) { all = false; break; }
                        if (all) best = area;
                    }
        return best;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int maxSubarraySumCircular(vector<int>& nums) {
        int n = nums.size();
        long long best = LLONG_MIN;
        for (int start = 0; start < n; start++) {
            long long sum = 0;
            for (int len = 1; len <= n; len++) {
                sum += nums[(start + len - 1) % n];
                best = max(best, sum);
            }
        }
        return (int)best;
    }
};

// Brute force: time O(n), space O(n)
void fill(TreeNode *node, int depth, vector<vector<int>> &levels) {
    if (!node) return;
    if ((int)levels.size() == depth) levels.push_back({});
    levels[depth].push_back(node->val);
    fill(node->left, depth + 1, levels);
    fill(node->right, depth + 1, levels);
}

class Solution {
public:
    vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
        vector<vector<int>> levels;
        fill(root, 0, levels);
        for (size_t i = 1; i < levels.size(); i += 2) reverse(levels[i].begin(), levels[i].end());
        return levels;
    }
};

// Brute force: time O(n^2), space O(n)
bool isPal(const string &s) {
    int i = 0, j = (int)s.size() - 1;
    while (i < j) {
        if (s[i++] != s[j--]) return false;
    }
    return true;
}

class Solution {
public:
    bool validPalindrome(string s) {
        if (isPal(s)) return true;
        for (size_t i = 0; i < s.size(); i++) {
            string t = s;
            t.erase(i, 1);
            if (isPal(t)) return true;
        }
        return false;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    bool isIsomorphic(string s, string t) {
        int n = s.size();
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                if ((s[i] == s[j]) != (t[i] == t[j])) return false;
        return true;
    }
};

// Brute force: time O(n^2), space O(1)
class Solution {
public:
    int firstUniqChar(string s) {
        int n = s.size();
        for (int i = 0; i < n; i++) {
            bool dup = false;
            for (int j = 0; j < n; j++) {
                if (i != j && s[i] == s[j]) { dup = true; break; }
            }
            if (!dup) return i;
        }
        return -1;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    bool repeatedSubstringPattern(string s) {
        int n = s.size();
        for (int len = 1; len <= n / 2; len++) {
            if (n % len != 0) continue;
            string built;
            for (int i = 0; i < n / len; i++) built += s.substr(0, len);
            if (built == s) return true;
        }
        return false;
    }
};

// Brute force: time O(n^2), space O(n)
class Solution {
public:
    int minAddToMakeValid(string s) {
        // repeatedly delete adjacent "()" pairs; whatever is left must be fixed
        size_t pos;
        while ((pos = s.find("()")) != string::npos) s.erase(pos, 2);
        return (int)s.size();
    }
};

// Brute force: time O(n * T), space O(1)
class Solution {
public:
    int findJudge(int n, vector<vector<int>>& trust) {
        for (int cand = 1; cand <= n; cand++) {
            bool trustsSomeone = false;
            int trustedBy = 0;
            for (auto &p : trust) {
                if (p[0] == cand) { trustsSomeone = true; break; }
                if (p[1] == cand) trustedBy++;
            }
            if (!trustsSomeone && trustedBy == n - 1) return cand;
        }
        return -1;
    }
};

// Brute force: time O((m+n) log(m+n)), space O(1)
class Solution {
public:
    void merge(vector<int>& nums1, int m, vector<int>& nums2, int n) {
        for (int i = 0; i < n; i++) nums1[m + i] = nums2[i];
        sort(nums1.begin(), nums1.end());
    }
};

// Brute force: time O(|b|), space O(1)
class Solution {
public:
    int getSum(int a, int b) {
        // step a one unit at a time, |b| times
        int step = b > 0 ? 1 : -1;
        for (int i = 0; i != b; i += step) a += step;
        return a;
    }
};

// Brute force: time O(n^3 + t log t) for t distinct triplets, space O(t)
class Solution {
public:
    vector<vector<int>> threeSum(vector<int>& nums) {
        int n = nums.size();
        set<vector<int>> found;
        for (int i = 0; i < n; i++)
            for (int j = i + 1; j < n; j++)
                for (int k = j + 1; k < n; k++)
                    if ((long long)nums[i] + nums[j] + nums[k] == 0) {
                        vector<int> t = {nums[i], nums[j], nums[k]};
                        sort(t.begin(), t.end());
                        found.insert(t);
                    }
        return vector<vector<int>>(found.begin(), found.end());
    }
};

// Brute force: time O(n^4), space O(t) for t distinct quadruplets
class Solution {
public:
    vector<vector<int>> fourSum(vector<int>& nums, int target) {
        int n = nums.size();
        set<vector<int>> found;
        for (int a = 0; a < n; a++)
            for (int b = a + 1; b < n; b++)
                for (int c = b + 1; c < n; c++)
                    for (int d = c + 1; d < n; d++)
                        if ((long long)nums[a] + nums[b] + nums[c] + nums[d] == target) {
                            vector<int> q = {nums[a], nums[b], nums[c], nums[d]};
                            sort(q.begin(), q.end());
                            found.insert(q);
                        }
        return vector<vector<int>>(found.begin(), found.end());
    }
};

// Brute force: time O(n! * n), space O(n! * n)
class Solution {
public:
    vector<vector<int>> permuteUnique(vector<int>& nums) {
        vector<int> cur = nums;
        sort(cur.begin(), cur.end());
        set<vector<int>> seen;
        do {
            seen.insert(cur);
        } while (next_permutation(cur.begin(), cur.end()));
        return vector<vector<int>>(seen.begin(), seen.end());
    }
};

// Brute force: time O(2^(2n) * n), space O(2^(2n))
class Solution {
public:
    vector<string> generateParenthesis(int n) {
        vector<string> out;
        int len = 2 * n;
        for (int mask = 0; mask < (1 << len); mask++) {
            string s;
            int balance = 0;
            bool ok = true;
            for (int i = 0; i < len && ok; i++) {
                bool open = (mask >> i) & 1;
                s += open ? '(' : ')';
                balance += open ? 1 : -1;
                if (balance < 0) ok = false;
            }
            if (ok && balance == 0) out.push_back(s);
        }
        return out;
    }
};

// Brute force: time exponential in target / smallest candidate, space O(target)
class Solution {
    void go(vector<int> &c, int idx, int left, vector<int> &cur, vector<vector<int>> &out) {
        if (left == 0) {
            out.push_back(cur);
            return;
        }
        if (idx == (int)c.size() || left < 0) return;
        cur.push_back(c[idx]);
        go(c, idx, left - c[idx], cur, out);   // use c[idx] once more
        cur.pop_back();
        go(c, idx + 1, left, cur, out);        // or move on to the next candidate
    }

public:
    vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
        vector<int> cur;
        vector<vector<int>> out;
        go(candidates, 0, target, cur, out);
        return out;
    }
};

// Brute force: time O(n^2 * 256), space O(1)
class Solution {
public:
    string minWindow(string s, string t) {
        int n = s.size(), m = t.size();
        int need[256] = {};
        for (unsigned char c : t) need[c]++;
        // try window lengths from shortest to longest
        for (int len = m; len <= n; len++) {
            for (int st = 0; st + len <= n; st++) {
                int have[256] = {};
                for (int i = st; i < st + len; i++) have[(unsigned char)s[i]]++;
                bool ok = true;
                for (int c = 0; c < 256; c++) if (have[c] < need[c]) { ok = false; break; }
                if (ok) return s.substr(st, len);
            }
        }
        return "";
    }
};

// Brute force: time O(n * (n + e)), space O(n) (a fresh colouring attempt from every start node)
class Solution {
public:
    bool isBipartite(vector<vector<int>>& graph) {
        int n = graph.size();
        for (int start = 0; start < n; start++) {
            vector<int> color(n, -1);
            color[start] = 0;
            queue<int> q;
            q.push(start);
            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (int v : graph[u]) {
                    if (color[v] == -1) { color[v] = color[u] ^ 1; q.push(v); }
                    else if (color[v] == color[u]) return false;
                }
            }
        }
        return true;
    }
};
